"code": "fn main() {\n    let number = 7;\n    // твой код\n}",
"solution": "fn main() {\n    let number = 7;\n    if number % 2 == 0 {\n        println!(\"чётное\");\n    } else {\n        println!(\"нечётное\");\n    }\n}",
"expect": "нечётное",
