"code": "// напиши функцию sum\n\nfn main() {\n    let arr = [1, 2, 3];\n    let v = vec![10, 20];\n    println!(\"{} {}\", sum(&arr), sum(&v));\n    println!(\"{}\", sum(&arr[1..]));\n}",
